:root {
  --tag-bg: #f2ece0;
  --tag-border: #8b6f47;
  --header-bg: #5a3e2b;
  --header-text: #f5e8c8;
  --swatch-color: #7a6a8a;
  --swatch-stripe: #5c4d6b;
  --color-name: #3b2a1a;
  --dye-source: #6b4f32;
  --footer-bg: #e8dcc8;
  --footer-text: #7a5c3a;
}

.skein-tag {
  width: 240px;
  background-color: var(--tag-bg);
  border: 2px solid var(--tag-border);
  border-radius: 6px;
  overflow: hidden;
  margin: 40px auto;
}

.tag-header {
  background-color: var(--header-bg);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 12px;
}

.studio-name {
  color: var(--header-text);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.04em;
}

.tag-number {
  color: var(--header-text);
  font-size: 11px;
  font-weight: 400;
  opacity: 0.75;
}

.dye-swatch {
  height: 48px;
  background-color: var(--swatch-color);
  border-top: 2px solid var(--swatch-stripe);
  border-bottom: 2px solid var(--swatch-stripe);
}

.tag-body {
  padding: 10px 12px 8px;
  text-align: center;
}

.color-name {
  margin: 0 0 4px;
  font-size: 16px;
  font-weight: 700;
  color: var(--color-name);
  letter-spacing: 0.02em;
}

.dye-source {
  margin: 0;
  font-size: 11px;
  color: var(--dye-source);
  letter-spacing: 0.03em;
}

.tag-footer {
  background-color: var(--footer-bg);
  display: flex;
  justify-content: space-between;
  padding: 7px 12px;
  border-top: 1px solid var(--tag-border);
}

.weight {
  font-size: 11px;
  font-weight: 600;
  color: var(--footer-text);
}

.date {
  font-size: 11px;
  color: var(--footer-text);
  opacity: 0.8;
}
